export const treeOfThoughtsReasoning = (input, evaluate, backtrack) => {
  const branches = [];
  const explorePath = (path) => {
    const result = evaluate(path);
    if (result.success) {
      branches.push(result);
    } else if (result.canBacktrack) {
      backtrack(path);
    }
  };
  explorePath(input);
  return branches.sort((a, b) => b.score - a.score)[0];
};